#include "bsp/native_renderer_container_lifetime.hpp"
#include "bsp/singleton_lifetime.hpp"
#include "native_renderer_container_reference.hpp"
#include <Windows.h>
#include <new.h>
#include <array>
#include <cstdio>
#include <cstring>
#include <limits>
#include <new>
#include <stdexcept>
#include <vector>

namespace {
using Routine = void (__fastcall*)(void*, std::uint32_t, std::int32_t);
struct Header { void* data; std::int32_t count; std::int32_t capacity; };
static_assert(sizeof(Header) == 12);
struct Frame { std::uint32_t before; Header header; std::uint32_t after; };
struct Spec {
    const char* name;
    const unsigned char* bytes;
    std::size_t size;
    std::size_t allocation;
    std::size_t release;
    std::uint32_t stride;
    Routine source;
};
int failure_calls;
void require(bool value, const char* message) {
    if (!value) throw std::runtime_error(message);
}
int __cdecl fail_allocation(std::size_t) { ++failure_calls; return 0; }
void* __cdecl allocate_original(std::uint32_t bytes) {
    return bsp::singleton_lifetime_allocate({bsp::SingletonAllocationKind::object, bytes, bytes});
}
void __cdecl release_original(void* data) noexcept { bsp::singleton_lifetime_free(data); }

void relocate(unsigned char* code, std::size_t site, std::uintptr_t target) {
    require(code[site] == 0xe8, "expected direct CALL");
    const auto displacement = static_cast<std::uint32_t>(target - reinterpret_cast<std::uintptr_t>(code + site + 5));
    std::memcpy(code + site + 1, &displacement, 4);
}
class Original {
    void* code_;
public:
    explicit Original(const Spec& spec) : code_(VirtualAlloc(nullptr, spec.size, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE)) {
        require(code_ != nullptr, "VirtualAlloc");
        std::memcpy(code_, spec.bytes, spec.size);
        auto* code = static_cast<unsigned char*>(code_);
        relocate(code, spec.allocation, reinterpret_cast<std::uintptr_t>(&allocate_original));
        relocate(code, spec.release, reinterpret_cast<std::uintptr_t>(&release_original));
        DWORD old_protection;
        require(VirtualProtect(code_, spec.size, PAGE_EXECUTE_READ, &old_protection) != 0, "VirtualProtect");
        require(FlushInstructionCache(GetCurrentProcess(), code_, spec.size) != 0, "FlushInstructionCache");
    }
    ~Original() { VirtualFree(code_, 0, MEM_RELEASE); }
    Routine function() const { return reinterpret_cast<Routine>(code_); }
};
void reset_x87() {
    unsigned short control = 0x037f;
    __asm { fnclex }
    __asm { fldcw control }
}
unsigned short status_x87() {
    unsigned short result;
    __asm { fnstsw result }
    return static_cast<unsigned short>(result & 0x003f);
}
struct Outcome { std::vector<unsigned char> rows; unsigned short x87; };
Outcome exercise(Routine routine, std::uint32_t stride, int scenario) {
    Frame frame{0x13579bdfu, {nullptr, 2, 2}, 0x2468ace0u};
    const std::uint32_t bytes = stride * 2;
    frame.header.data = allocate_original(bytes);
    auto* words = static_cast<std::uint32_t*>(frame.header.data);
    for (std::uint32_t word = 0; word < bytes / 4; ++word) words[word] = 0x7f800001u + word;
    const auto old = frame.header;
    Outcome result;
    reset_x87();
    if (scenario == 0) {
        routine(&frame.header, 0x98765432u, 4);
        result.x87 = status_x87();
        require(frame.header.data != old.data && frame.header.count == 2 && frame.header.capacity == 4, "grow header");
    } else if (scenario == 1) {
        routine(&frame.header, 0, -7);
        result.x87 = status_x87();
        require(frame.header.data == old.data && frame.header.count == 2 && frame.header.capacity == 2, "clamped no-grow header");
    } else if (scenario == 2) {
        release_original(frame.header.data);
        frame.header = {nullptr, 0, -1};
        routine(&frame.header, 0, 0);
        result.x87 = status_x87();
        require(frame.header.data != nullptr && frame.header.count == 0 && frame.header.capacity == 1, "zero-resize reserve header");
    } else {
        failure_calls = 0;
        const auto previous = _set_new_handler(&fail_allocation);
        bool caught = false;
        try { routine(&frame.header, 0, (std::numeric_limits<std::int32_t>::max)()); }
        catch (const std::bad_alloc&) { caught = true; }
        _set_new_handler(previous);
        result.x87 = status_x87();
        require(caught && failure_calls == 1, "allocation failure propagation");
        require(std::memcmp(&frame.header, &old, sizeof old) == 0, "failure preserves header");
    }
    require(frame.before == 0x13579bdfu && frame.after == 0x2468ace0u, "header guards");
    const auto copied = static_cast<std::size_t>(frame.header.count) * stride;
    result.rows.resize(copied);
    if (copied != 0) std::memcpy(result.rows.data(), frame.header.data, copied);
    release_original(frame.header.data);
    return result;
}
}
int main() {
    const Spec specs[] = {
        {"00b228b0", original_00b228b0, sizeof original_00b228b0, allocation_site_00b228b0, release_site_00b228b0, 16, &bsp::reserve_native_renderer_records16_00b228b0},
        {"00b22940", original_00b22940, sizeof original_00b22940, allocation_site_00b22940, release_site_00b22940, 20, &bsp::reserve_native_renderer_records20_00b22940},
        {"00b229d0", original_00b229d0, sizeof original_00b229d0, allocation_site_00b229d0, release_site_00b229d0, 24, &bsp::reserve_native_renderer_records24_00b229d0},
        {"00b22a70", original_00b22a70, sizeof original_00b22a70, allocation_site_00b22a70, release_site_00b22a70, 40, &bsp::reserve_native_renderer_records40_00b22a70}
    };
    try {
        for (const auto& spec : specs) {
            Original original(spec);
            for (int scenario = 0; scenario < 4; ++scenario) {
                const auto expected = exercise(original.function(), spec.stride, scenario);
                const auto actual = exercise(spec.source, spec.stride, scenario);
                require(actual.rows == expected.rows, "original/source bytes");
                require(actual.x87 == expected.x87, "original/source x87 status");
                require(actual.x87 == (scenario == 0 ? 1 : 0), "masked signaling-NaN status");
            }
            std::printf("PASS %s: growth x87 bytes/status, clamped no-grow, negative-capacity resize0, allocation failure\n", spec.name);
        }
        std::puts("PASS: four complete original bodies against main-archive source; 16 comparisons");
        return 0;
    } catch (const std::exception& error) {
        std::fprintf(stderr, "FAIL: %s\n", error.what());
        return 1;
    }
}
